import React, { useEffect, useState, useCallback } from 'react';
import Navbar from '../components/Navbar';
import CategoryPanel from '../components/CategoryPanel';
import Gallery from '../components/Gallery';
import './Home.css';

const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

function Home() {
  const [artworks, setArtworks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [category, setCategory] = useState('paintings');
  const [search, setSearch] = useState('');

  const fetchArtworks = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (category) params.set('category', category);
      if (search) params.set('q', search);

      const res = await fetch(`${API_BASE}/artworks?${params.toString()}`);
      if (!res.ok) throw new Error('Failed to fetch artworks');
      const data = await res.json();
      setArtworks(data);
    } catch (err) {
      console.error(err);
      setArtworks([]);
    } finally {
      setLoading(false);
    }
  }, [category, search]);

  useEffect(() => {
    fetchArtworks();
  }, [fetchArtworks]);

  return (
    <div className="home">
      <Navbar onSearch={setSearch} />
      <main className="home__body">
        <CategoryPanel active={category} onSelect={setCategory} />
        <Gallery artworks={artworks} loading={loading} />
      </main>

      <footer className="footer">
        <div className="footer__top">
          <div className="footer__brand-block">
            <div className="footer__brand-mark">K</div>
            <div className="footer__brand-copy">
              <h3>KalaSpace</h3>
              <span>Global</span>
            </div>
          </div>

          <div className="footer__links">
            <div>
              <h4>Explore</h4>
              <a href="#gallery">Gallery</a>
              <a href="#paintings">Paintings</a>
              <a href="#artists">Artists</a>
            </div>

            <div>
              <h4>Company</h4>
              <a href="#about">About Us</a>
              <a href="#sell">Sell Art</a>
              <a href="#journal">Journal</a>
            </div>

            <div>
              <h4>Connect</h4>
              <a href="#contact">Contact</a>
              <a href="#support">Support</a>
              <a href="#faq">FAQ</a>
            </div>
          </div>
        </div>

        <div className="footer__bottom">
          <p>© 2026 KalaSpace Global</p>
          <p>Curating modern art for a global audience.</p>
        </div>
      </footer>
    </div>
  );
}

export default Home;
